`timescale 1ns / 1ps

// exact_booth -- structural exact signed 8 x 8 radix-4 Booth multiplier (b Booth-encoded,
// zero-digit-gated negation, inverted-sign-bit sign extension, Dadda reduction with 15 full and
// 9 half adders, final carry-propagate adder). Exact baseline of the approximate-multiplier
// study; generated by src_int8.approx.rtl.gen_booth (do not edit). Same ports and function as
// src_int8/rtl/int/mq_mul8.v.
module mq_fa (input wire x, y, z, output wire s, c);
    assign s = x ^ y ^ z;
    assign c = (x & y) | (z & (x ^ y));
endmodule

module mq_ha (input wire x, y, output wire s, c);
    assign s = x ^ y;
    assign c = x & y;
endmodule

