    mq_ha u0 (.x((((one0 & a[6]) | (two0 & a[5])) ^ neg0)), .y((((one1 & a[4]) | (two1 & a[3])) ^ neg1)), .s(s0), .c(c0));
    mq_ha u1 (.x((((one0 & a[7]) | (two0 & a[6])) ^ neg0)), .y((((one1 & a[5]) | (two1 & a[4])) ^ neg1)), .s(s1), .c(c1));
