    mq_ha u23 (.x((((one3 & a[7]) | (two3 & a[6])) ^ neg3)), .y(1'b1), .s(s23), .c(c23));
    wire [15:0] r0 = {1'b1, ~(((one3 & a[7]) | (two3 & a[7])) ^ neg3), c22, c21, c20, c19, c18, c17, c16, c15, c14, c13, c12, neg1, (((one0 & a[1]) | (two0 & a[0])) ^ neg0), (((one0 & a[0])) ^ neg0)};
    wire [15:0] r1 = {1'b0, c23, s23, s22, s21, s20, s19, s18, s17, s16, s15, s14, s13, s12, 1'b0, neg0};
